class Solution {
    int atMost(vector<int>& nums,int limit){
        unordered_map<int,int> frequency;
        int left=0,distinct=0,count=0;
        for(int right=0;right<(int)nums.size();++right){
            if(frequency[nums[right]]++==0)++distinct;
            while(distinct>limit){
                int value=nums[left++];
                if(--frequency[value]==0)--distinct;
            }
            count+=right-left+1;
        }
        return count;
    }
    public:int subarraysWithKDistinct(vector<int>& nums,int k){
        return atMost(nums,k)-atMost(nums,k-1);
    }
};
